///|
suberror AdapterError {
  AdapterError(String)
} derive(@debug.Debug)

///|
impl Show for AdapterError with fn output(self, logger) {
  logger.write_string(diagnostic_error(self))
}

///|
fn required(value : Json, name : String) -> String raise {
  match field(value, name) {
    Some(Json::String(text)) if text != "" => text
    _ => raise AdapterError("Missing or invalid \{name}")
  }
}

///|
fn environment(name : String) -> String raise {
  match @env.get_env_var(name) {
    Some(value) if value != "" => value
    _ => raise AdapterError("Missing \{name}")
  }
}

///|
fn quote(text : String) -> String {
  let escaped_quote =
    #|'"'"'
  "'" + text.replace_all(old="'", new=escaped_quote) + "'"
}

///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> (Int32, String, String) {
  let recording = recording_override.unwrap_or(
    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0"),
  )
  let context : Json? = if recording {
    diagnostic_operation_counter.val += 1
    let value : Json = {
      "operationId": recording_run_id +
      ":" +
      diagnostic_operation_counter.val.to_string(),
    }
    if target is Some(id) {
      set_field(value, "workspaceId", Json::string(id))
    }
    Some(value)
  } else {
    None
  }
  save_diagnostic(
    stage,
    "started",
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets?,
    recording~,
  )
  let started = @env.now()
  let progress = Progress::new(
    stage,
    environment?,
    context?,
    recording_override=recording,
    protected_secrets?,
    protection_incomplete~,
  )
  let label = target.map(value => value + ": " + stage).unwrap_or(stage)
  progress_message(label + ": running…")
  let mut failure_kind = "process_api"
  let mut failure_errno = None
  let mut failure_phase = None
  let (status, output, errors) = {
    errdefer {
      save_diagnostic(
        stage,
        if @async.is_being_cancelled() {
          "cancelled"
        } else {
          "process-error"
        },
        error_type=failure_kind,
        os_errno?=failure_errno,
        phase?=failure_phase,
        error_message=progress.failure_detail(),
        details_truncated=progress.details_truncated,
        evidence?=context,
        evidence_stable_operation=true,
        environment?,
        protected_secrets?,
        recording~,
      )
      progress_message(label + ": failed (" + progress_timing(started) + ")")
    }
    try {
      let (out, stdout) = @process.read_from_process()
      defer out.close()
      let (err, stderr) = @process.read_from_process()
      defer err.close()
      @async.with_task_group(async fn(group) {
        let child = @process.spawn(
          group,
          program,
          args,
          extra_env?=environment,
          inherit_env=environment is None,
          cwd?,
          stdout~,
          stderr~,
        )
        let output = group.spawn(async fn() {
          progress.read_output(
            out,
            capture=true,
            statuses=devsy_progress_stage(stage),
            messages=stage == "orca-install" || stage == "checkout-workspace",
          )
        })
        let errors = group.spawn(async fn() {
          progress.read_output(
            err,
            capture=false,
            messages=devsy_progress_stage(stage) ||
              stage == "orca-install" ||
              stage == "checkout-workspace",
          )
        })
        (child.wait(), output.wait(), errors.wait())
      })
    } catch {
      @os_error.OSError(code, ..) as error => {
        failure_kind = "process_os"
        failure_errno = Some(code)
        let message = if protection_incomplete {
          progress.details_truncated = true
          "subprocess OS error \{code}; workspace protection values unavailable"
        } else {
          progress
          .safe_message(program + ": " + error.to_string())
          .unwrap_or("subprocess OS error \{code}")
        }
        progress.remember(message, warning=true)
        raise AdapterError(
          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
          message,
        )
      }
      @utf8.Malformed(_) => {
        failure_kind = "process_utf8"
        failure_phase = Some("read")
        progress.remember("subprocess output is not valid UTF-8", warning=true)
        raise AdapterError(
          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
        )
      }
      error => {
        if !@async.is_being_cancelled() {
          let detail = if protection_incomplete {
            progress.details_truncated = true
            "error detail unavailable because workspace protection values could not be read"
          } else {
            diagnostic_text(
              diagnostic_error(error, environment?),
              environment?,
              protected_secrets=progress.secrets,
            )
          }
          for line in detail.split("\n") {
            progress.remember(line.to_owned(), warning=true)
          }
        }
        raise error
      }
    }
  }
  progress_message(
    label +
    ": " +
    (if status == 0 { "done" } else { "failed (exit \{status})" }) +
    " (" +
    progress_timing(started) +
    ")",
  )
  save_diagnostic(
    stage,
    if status == 0 {
      "success"
    } else {
      "exit-error"
    },
    exit_code=status,
    duration_ms=(@env.now() - started).to_double(),
    error_message?=if status == 0 {
      None
    } else {
      Some(progress.failure_detail())
    },
    details_truncated=progress.details_truncated,
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets?,
    error_type?=if status == 0 || !recording {
      None
    } else {
      Some(process_error_type(output + "\n" + errors))
    },
    recording~,
  )
  (status, output, progress.failure_detail())
}

///|
fn command_failure(stage : String, status : Int32, detail : String) -> String {
  "\{stage} failed (exit \{status}); diagnostic run \{recording_run_id}:\n" +
  detail
}

///|
async fn command(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> String {
  let (status, output, detail) = command_result(
    program,
    args,
    stage,
    environment?,
    cwd?,
    target?,
    recording_override?,
    protected_secrets?,
    protection_incomplete~,
  )
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn devsy_args(state : Json) -> Array[String] {
  let args = []
  for name in ["home", "context", "provider"] {
    if field(state, name) is Some(Json::String(value)) {
      args.push("--" + name)
      args.push(value)
    }
  }

///|
fn credential_field(name : String) -> Bool {
  let chars = name.trim_start(chars="-").iter().to_array()
  let normalized = @buffer.Buffer(size_hint=name.length())
  for i in 0..<chars.length() {
    let c = chars[i]
    if i > 0 &&
      c >= 'A' &&
      c <= 'Z' &&
      (
        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
      ) {
      normalized.write_char_utf8('_')
    }
    normalized.write_char_utf8(if c == '-' { '_' } else { c })
  }
  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
  [
    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
    "x_amz_security_token", "x_goog_signature",
  ].contains(name) ||
  name
  .split("_")
  .iter()
  .any(part => {
    [
      "auth", "authorization", "cookie", "password", "passwd", "passphrase", "token",
      "secret", "apikey", "credential", "credentials", "signature", "pairingcode",
      "privatekey", "clientsecret", "accesstoken", "refreshtoken", "proxyauthorization",
      "setcookie",
    ].contains(part.to_owned())
  }) ||
  name.contains("_api_key_") ||
  name.has_prefix("api_key_") ||
  name.has_suffix("_api_key") ||
  name.contains("_private_key_") ||
  name.has_prefix("private_key_") ||
  name.has_suffix("_private_key") ||
  name == "pairing_code" ||
  name.contains("_pairing_code_") ||
  name.has_prefix("pairing_code_") ||
  name.has_suffix("_pairing_code")
}

///|
fn credential_word(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') ||
  (c >= 'A' && c <= 'Z') ||
  (c >= '0' && c <= '9') ||
  c == '_' ||
  c == '-'
}

///|
fn credential_space(c : Char) -> Bool {
  c == ' ' || c == '\t'
}

///|
fn credential_end(c : Char) -> Bool {
  credential_space(c) ||
  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
}

///|
fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
  let buffer = @buffer.Buffer(size_hint=end - start)
  for i in start..<end {
    buffer.write_char_utf8(chars[i])
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn credential_hex(c : Char) -> Int32? {
  match c {
    '0'..<='9' => Some(c.to_int() - '0'.to_int())
    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
    _ => None
  }
}

///|
fn credential_parameter(name : String) -> String {
  let chars = name.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=name.length())
  let mut i = 0
  while i < chars.length() {
    if chars[i] == '%' &&
      i + 2 < chars.length() &&
      credential_hex(chars[i + 1]) is Some(hi) &&
      credential_hex(chars[i + 2]) is Some(lo) {
      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
      i += 3
    } else {
      buffer.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn redact_credentials(text : String) -> String {
  let chars = text.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  let mut url = false
  while i < chars.length() {
    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
      url = false
    }
    if chars[i] == ':' &&
      i + 2 < chars.length() &&
      chars[i + 1] == '/' &&
      chars[i + 2] == '/' {
      url = true
      buffer.write_string_utf8("://")
      i += 3
      let mut end = i
      let mut user_end = None
      while end < chars.length() &&
            !credential_end(chars[end]) &&
            !['/', '?'].contains(chars[end]) {
        if chars[end] == '@' {
          user_end = Some(end)
        }
        end += 1
      }
      if user_end is Some(end) {
        buffer.write_string_utf8("[redacted]@")
        i = end + 1
      }
      continue
    }
    if url && ['?', '&'].contains(chars[i]) {
      let start = i
      i += 1
      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
        i += 1
      }
      let name = credential_parameter(character_text(chars, start + 1, i))
      if i < chars.length() && chars[i] == '=' {
        i += 1
        buffer.write_string_utf8(character_text(chars, start, i))
        if credential_field(name) || ["key", "code"].contains(name.to_lower()) {
          if i + 10 <= chars.length() &&
            character_text(chars, i, i + 10) == "[redacted]" {
            i += 10
          }
          while i < chars.length() && !credential_end(chars[i]) {
            i += 1
          }
          buffer.write_string_utf8("[redacted]")
        }
      } else {
        buffer.write_string_utf8(character_text(chars, start, i))
      }
      continue
    }
    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
      let start = i
      let mut end = i
      while end < chars.length() && credential_word(chars[end]) {
        end += 1
      }
      let word = character_text(chars, start, end)
      let lower = word.to_lower()
      if [
          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
        ]
        .iter()
        .any(prefix => lower.has_prefix(prefix)) ||
        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
        while end < chars.length() && !credential_end(chars[end]) {
          end += 1
        }
        buffer.write_string_utf8("[redacted]")
        i = end
        continue
      }
      let mut separator = end
      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
        separator += 1
      }
      while separator < chars.length() && credential_space(chars[separator]) {
        separator += 1
      }
      if ["bearer", "basic"].contains(lower) &&
        separator > end &&
        separator < chars.length() {
        let mut value_end = separator
        if separator + 10 <= chars.length() &&
          character_text(chars, separator, separator + 10) == "[redacted]" {
          value_end = separator + 10
        }
        while value_end < chars.length() && !credential_end(chars[value_end]) {
          value_end += 1
        }
        let value = character_text(chars, separator, value_end).to_lower()
        if value_end > separator &&
          !["authentication", "auth", "token"].contains(value) {
          buffer.write_string_utf8(character_text(chars, start, separator))
          buffer.write_string_utf8("[redacted]")
          i = value_end
          continue
        }
      }
      let mut previous = start
      while previous > 0 && credential_space(chars[previous - 1]) {
        previous -= 1
      }
      let field_start = previous == 0 ||
        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
      let option = word.has_prefix("--")
      let prose_credential = (
          ["credential", "credentials"].contains(lower) && !field_start
        ) ||
        lower == "ssh_inject_git_credentials"
      let assignment = separator < chars.length() &&
        (
          chars[separator] == '=' ||
          (chars[separator] == ':' && !prose_credential)
        )
      if credential_field(word) && (assignment || (option && separator > end)) {
        let mut value = if assignment { separator + 1 } else { separator }
        while value < chars.length() && credential_space(chars[value]) {
          value += 1
        }
        buffer.write_string_utf8(character_text(chars, start, value))
        let quoted_key = start > 0 &&
          end < chars.length() &&
          ['"', '\''].contains(chars[start - 1]) &&
          chars[start - 1] == chars[end]
        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
          buffer.write_string_utf8("[redacted]")
          i = chars.length()
        } else if value + 10 <= chars.length() &&
          character_text(chars, value, value + 10) == "[redacted]" {
          buffer.write_string_utf8("[redacted]")
          i = value + 10
          while i < chars.length() && !credential_end(chars[i]) {
            i += 1
          }
        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
          let quote = chars[value]
          buffer.write_char_utf8(quote)
          value += 1
          while value < chars.length() && chars[value] != quote {
            if chars[value] == '\\' && value + 1 < chars.length() {
              value += 1
            }
            value += 1
          }
          buffer.write_string_utf8("[redacted]")
          i = value
        } else {
          let mut value_end = value
          while value_end < chars.length() && !credential_end(chars[value_end]) {
            value_end += 1
          }
          let scheme = character_text(chars, value, value_end).to_lower()
          if scheme == "bearer" || scheme == "basic" {
            while value_end < chars.length() &&
                  credential_space(chars[value_end]) {
              value_end += 1
            }
            buffer.write_string_utf8(character_text(chars, value, value_end))
            value = value_end
            while value_end < chars.length() &&
                  !credential_end(chars[value_end]) {
              value_end += 1
            }
          }
          if value + 10 <= chars.length() &&
            character_text(chars, value, value + 10) == "[redacted]" {
            value_end = value + 10
          }
          if value_end > value {
            buffer.write_string_utf8("[redacted]")
          }
          i = value_end
        }
        continue
      }
      buffer.write_string_utf8(word)
      i = end
      continue
    }
    buffer.write_char_utf8(chars[i])
    i += 1
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  guard terminal_text(text) is Some(text) else { return None }
  let lower = text.to_lower()
  if lower.contains("-----begin ") && lower.contains("private key-----") {
    self.private_key = REDACTED ")
    return Some("[private key redacted]")
  }
  if self.private_key {
    if lower.contains("-----end ") && lower.contains("private key-----") {
      self.private_key = false
    }
    return None
  }
  let known = redact_known_values(text, self.secrets)
  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}

///|
fn redact_known_values(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let values : Array[Array[Char]] = []
  for secret in secrets {
    if secret.length() <= text.length() {
      values.push(secret.iter().to_array())
    }
  }
  let result = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    let mut matched = 0
    for index in 0..<values.length() {
      let value = values[index]
      let mut matches = value.length() > 0 &&
        i + value.length() <= chars.length()
      if matches {
        for j in 0..<value.length() {
          if chars[i + j] != value[j] {
            matches = false
            break
          }
        }
      }
      if matches &&
        (
          value.length() > 10 ||
          i + 10 > chars.length() ||
          character_text(chars, i, i + 10) != "[redacted]"
        ) {
        matched = value.length()
        break
      }
    }
    if matched > 0 {
      result.write_string_utf8("[redacted]")
      i += matched
    } else if i + 10 <= chars.length() &&
      character_text(chars, i, i + 10) == "[redacted]" {
      result.write_string_utf8("[redacted]")
      i += 10
    } else {
      result.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

async fn try_flush_diagnostic_recording() -> Unit {
  if diagnostic_write_active.val ||
    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
    return
  }
  diagnostic_write_active.val = true
  defer {
    diagnostic_write_active.val = false
  }
  let mut failure_phase = "directory"
  let mut health_changed = false
  @async.with_timeout(50, async fn() {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    let lock_path = dir + "/events.lock"
    failure_phase = "lock"
    if @fs.exists(lock_path) &&
      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
      return
    }
    let lock = @fs.open(
      lock_path,
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    if !lock.try_lock(Exclusive) {
      diagnostic_recording_warning("lock_busy", phase=failure_phase)
      return
    }
    failure_phase = "inspect"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_warning("invalid_store", phase=failure_phase)
      return
    }
    let mut prefix = ""
    let mut replace = false
    let mut prefix_markers = 0
    let mut retained : String? = None
    let terminal = diagnostic_pending
      .iter()
      .any(pending => {
        field(pending.event, "stage") == Some(Json::string("diagnostic-run")) &&
        field(pending.event, "status") == Some(Json::string("finished"))
      })
    if @fs.exists(path) {
      let file = @fs.open(path, mode=ReadOnly)
      defer file.close()
      let size = file.size()
      if size > 262144L {
        let marker = diagnostic_recording_event("rotated", "retention_limit")
        set_field(
          marker,
          "missingThroughTime",
          Json::string(@env.now().to_string()),
        )
        set_field(marker, "missingRange", Json::string("unknown"))
        let records = diagnostic_retained_records(file, size)
        retained = Some(records)
        prefix = marker.stringify() + "\n" + records
        prefix_markers += 1
        replace = true
      } else if size > 0L {
        let tail = FixedArray::make(1, b'\x00')
        guard file.read_at(tail, position=size - 1L) == 1 else {
          raise AdapterError("Unable to inspect diagnostic record boundary")
        }
        if tail[0] != b'\n' {
          let bytes = FixedArray::make(size.to_int(), b'\x00')
          let read = file.read_at(bytes, position=0L)
          let mut complete = read
          while complete > 0 && bytes[complete - 1] != b'\n' {
            complete -= 1
          }
          prefix = @utf8.decode_lossy(
            bytes.unsafe_reinterpret_as_bytes()[:complete],
          )
          let marker = diagnostic_recording_event(
            "degraded",
            if read != size.to_int() {
              "short_read"
            } else {
              "incomplete_record"
            },
          )
          set_field(marker, "missingRange", Json::string("unknown"))
          prefix += marker.stringify() + "\n"
          prefix_markers += 1
          retained = Some(
            @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:complete]),
          )
          replace = true
        }
      }
      if terminal && retained is None {
        let bytes = FixedArray::make(size.to_int(), b'\x00')
        let read = file.read_at(bytes, position=0L)
        if read != size.to_int() {
          raise AdapterError("Unable to inspect complete diagnostic records")
        }
        retained = Some(@utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()))
      }
    } else if terminal {
      retained = Some("")
    }
    if retained is Some(records) &&
      diagnostic_current_run_count(records) < diagnostic_run_written_count.val {
      diagnostic_recording_health.run_partial = true
    }
    if terminal && diagnostic_recording_health.run_partial {
      for pending in diagnostic_pending {
        if field(pending.event, "stage") == Some(Json::string("diagnostic-run")) &&
          field(pending.event, "status") == Some(Json::string("finished")) {
          set_field(pending.event, "runCompleteness", Json::string("partial"))
        }
      }
    }
    let recorded_drops = diagnostic_recording_health.dropped
    let incident_serial = diagnostic_recording_health.incident_serial
    if recorded_drops > 0 || diagnostic_recording_health.incident {
      let marker = diagnostic_recording_event(
        if recorded_drops > 0 {
          "degraded"
        } else {
          "recovered"
        },
        diagnostic_recording_health.reason,
      )
      if recorded_drops > 0 {
        set_field(
          marker,
          "droppedEvents",
          Json::number(recorded_drops.to_double()),
        )
        set_field(
          marker,
          "missingFromTime",
          Json::string(diagnostic_recording_health.first_dropped.to_string()),
        )
        set_field(
          marker,
          "missingThroughTime",
          Json::string(diagnostic_recording_health.last_dropped.to_string()),
        )
      } else {
        set_field(marker, "completeness", Json::string("complete"))
      }
      if diagnostic_recording_health.phase != "" {
        set_field(
          marker,
          "phase",
          Json::string(diagnostic_recording_health.phase),
        )
      }
      if diagnostic_recording_health.os_errno is Some(code) {
        set_field(marker, "osErrno", Json::number(code.to_double()))
      }
      prefix += marker.stringify() + "\n"
      prefix_markers += 1
    }
    let count = diagnostic_pending.length()
    diagnostic_pending_inflight.val = count
    defer {
      diagnostic_pending_inflight.val = 0
    }
    let records = @buffer.Buffer(size_hint=4096)
    for index in 0..<count {
      records.write_string_utf8(
        diagnostic_pending[index].event.stringify() + "\n",
      )
    }
    let content = prefix + @utf8.decode_lossy(records.to_bytes())
    failure_phase = if replace { "replace" } else { "append" }
    if replace {
      let temporary = path + ".rotate." + proxy_pid().to_string()
      defer (@fs.remove(temporary) catch { _ => () })
      @fs.write_file(temporary, content, permission=0o600)
      @fs.rename(temporary, path, replace=true)
    } else {
      @fs.write_file(
        path,
        content,
        permission=0o600,
        append=true,
        create_mode=OpenOrCreate,
      )
    }
    diagnostic_run_written_count.val += prefix_markers
    for index in 0..<count {
      if field(diagnostic_pending[index].event, "runId") ==
        Some(Json::string(recording_run_id)) {
        diagnostic_run_written_count.val += 1
      }
    }
    for _ in 0..<count {
      ignore(diagnostic_pending.remove(0))
    }
    diagnostic_previous_losses.clear()
    diagnostic_recording_health.dropped -= recorded_drops
    if diagnostic_recording_health.incident_serial == incident_serial {
      diagnostic_recording_health.incident = false
      health_changed = true
    }
  }) catch {
    error =>
      if !@async.is_being_cancelled() {
        diagnostic_recording_warning(
          if error is @async.TimeoutError {
            "store_timeout"
          } else {
            "store_unavailable"
          },
          phase=failure_phase,
          os_errno?=match error {
            @os_error.OSError(code, ..) => Some(code)
            _ => None
          },
        )
      }
  }
  if health_changed {
    publish_diagnostic_health()
    if diagnostic_recording_health.incident {
      publish_diagnostic_health()
    }
  }
}

///|
async fn flush_diagnostic_recording() -> Unit {
  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
    return
  }
  @async.with_timeout(1000, async fn() {
    while !diagnostic_pending.is_empty() ||
          diagnostic_recording_health.dropped > 0 {
      try_flush_diagnostic_recording()
      if !diagnostic_pending.is_empty() ||
        diagnostic_recording_health.dropped > 0 {
        @async.sleep(25)
      }
    }
  }) catch {
    error => if @async.is_being_cancelled() { raise error }
  }
}

///|
async fn finish_diagnostic_recording() -> Unit {
  flush_diagnostic_recording()
  if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
    diagnostic_recording_health.run_partial = true
    publish_diagnostic_health()
    return
  }
  if diagnostic_run_has_events.val {
    save_diagnostic(
      "diagnostic-run",
      "finished",
      run_completeness=if diagnostic_recording_health.run_partial {
        "partial"
      } else {
        "complete"
      },
      recording=true,
    )
    flush_diagnostic_recording()
    if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
      diagnostic_recording_health.run_partial = true
      publish_diagnostic_health()
    }
  }
}

///|
let recording_run_id : String = @env.now().to_string() +
  "_" +
