+  } else {
+    let value = try {
+      guard diagnostic_read_file(directory + "/environment.json", 4194304L)
+        is Some(raw) else {
+        raise AdapterError("Saved recording settings unavailable")
+      }
+      let environment = @json.parse(raw)
+      guard environment is Json::Object(_) else {
+        raise AdapterError("Invalid saved recording settings")
+      }
+      Some(recording_from_environment(environment))
+    } catch {
+      error => if @async.is_being_cancelled() { raise error } else { None }
+    }
+    if value is None {
+      diagnostic_recording_warning(
+        "workspace_recording_unknown",
+        phase="configuration",
+      )
+    }
+    value.unwrap_or(false)
+  }
+  set_field(state, "diagnosticRecording", Json::boolean(enabled))
+}
+
+///|
+async fn saved_workspace_secrets(
+  state : Json,
+  for_output~ : Bool = false,
+  include_pairing~ : Bool = true,
+) -> Array[String]? {
+  if !for_output && !state_recording(state) {
+    return Some([])
+  }
+  try {
+    let directory = required(state, "tunnelDirectory")
+    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
+      is Some(raw) else {
+      return None
+    }
+    let saved = @json.parse(raw)
+    guard saved is Json::Object(values) else { return None }
+    let environment : Map[String, String] = Map([])
+    for name, value in values {
+      guard value is Json::String(value) else { return None }
+      environment.set(name, value)
+    }
+    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
+    if include_pairing {
+      guard workspace_pairing_secrets(state) is Some(pairing) else {
+        return None
+      }
+      for value in pairing {
+        secrets.push(value)
+      }
+    }
+    Some(secrets)
+  } catch {
+    error => if @async.is_being_cancelled() { raise error } else { None }
+  }
+}
+
+///|
+async fn workspace_output_secrets(state : Json) -> Array[String]? {
+  guard field(state, "tunnelDirectory") is Some(Json::String(directory)) else {
+    return Some([])
+  }
+  if !@fs.exists(directory + "/state.json") &&
+    !@fs.exists(directory + "/environment.json") &&
+    !@fs.exists(directory + "/pairing-code") {
+    return Some([])
+  }
+  saved_workspace_secrets(state, for_output=true)
+}
+
+///|
+async fn workspace_pairing_value(state : Json) -> String? {
+  try {
+    let path = required(state, "tunnelDirectory") + "/pairing-code"
+    if !@fs.exists(path) {
+      return Some("")
+    }
+    diagnostic_read_file(path, 65536L)
+  } catch {
+    error => if @async.is_being_cancelled() { raise error } else { None }
+  }
+}
+
+///|
+async fn workspace_pairing_secrets(state : Json) -> Array[String]? {
+  guard workspace_pairing_value(state) is Some(pairing) else { return None }
+  let secrets = []
+  add_protected_secret(secrets, pairing)
+  Some(secrets)
+}
+
+///|
+async fn workspace_error_detail(state : Json, error : Error) -> String {
+  let environment = workspace_environment(state)
+  guard saved_workspace_secrets(state, for_output=true) is Some(secrets) else {
+    return "Error detail unavailable because workspace protection values could not be read"
+  }
+  diagnostic_text(
+    diagnostic_error(error, environment~),
+    environment~,
+    protected_secrets=secrets,
+  )
+}
+
+///|
+async fn record_discovery_error(
+  stage : String,
+  directory : String,
+  phase : String,
+  error : Error,
+) -> (Bool, Array[String]) {
+  let tracking : Json = { "tunnelDirectory": directory }
+  snapshot_workspace_recording(tracking, directory)
+  if !operation_recording(tracking) {
+    return (false, [])
+  }
+  guard saved_workspace_secrets(tracking) is Some(secrets) else {
+    suppress_workspace_recording(tracking)
+    return (false, [])
+  }
+  save_diagnostic(
+    stage,
+    "failed",
+    error_type="saved_state_invalid",
+    phase~,
+    tunnel_directory=directory,
+    error_message=diagnostic_error(error),
+    protected_secrets=secrets,
+    recording=true,
+  )
+  (true, secrets)
+}
+
+///|
+async fn record_selection_failure(
+  stage : String,
+  state : Json,
+  phase : String,
+  error_type : String,
+  detail : String,
+) -> Unit {
+  let directory = required(state, "tunnelDirectory")
+  snapshot_workspace_recording(state, directory)
+  if !operation_recording(state) {
+    return
+  }
+  guard saved_workspace_secrets(state) is Some(secrets) else {
+    suppress_workspace_recording(state)
+    return
+  }
+  save_diagnostic(
+    stage,
+    "failed",
+    error_type~,
+    phase~,
+    tunnel_directory=directory,
+    error_message=detail,
+    evidence={ "workspaceId": required(state, "workspaceId") },
+    environment=workspace_environment(state),
+    protected_secrets=secrets,
+    recording=true,
+  )
+}
+
+///|
+async fn suppress_workspace_recording(state : Json) -> Unit {
+  if state_recording(state) {
+    diagnostic_recording_failed(
+      "protected_values_unavailable",
+      phase="redaction",
+    )
+  }
+  set_field(state, "diagnosticRecording", Json::boolean(false))
+}
+
+///|
+fn operation_recording(state : Json) -> Bool {
+  @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
+  workspace_recording(state)
+}
+
+///|
+fn state_recording(state : Json) -> Bool {
+  match @env.args() {
+    [_, "--supervisor" | "--ssh-proxy", ..] => workspace_recording(state)
+    _ => operation_recording(state)
+  }
+}

