///|
async test "concurrent processes report any dropped records and keep distinct runs" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  @fs.write_file(root + "/events.jsonl", "{\"stage\":\"old\"}\n".repeat(20000))
  let warnings : Ref[Int32] = { val: 0, }
  @async.with_task_group(async fn(group) {
    let pending = []
    for _ in 0..<8 {
      pending.push(
        group.spawn(async fn() {
          let (status, _, errors) = bulk_fixture_run(
            ["status", "--provider", "fixture-provider"],
            env,
          )
          assert_eq(status, 0, msg=errors)
          if errors.contains("diagnostic recording is unavailable") {
            warnings.val += 1
          }
        }),
      )
    }
    for task in pending {
      task.wait()
    }
  })
  let events = fixture_events(directory)
  let starts = events.filter(event => {
    field(event, "stage") == Some(Json::string("bulk")) &&
    field(event, "status") == Some(Json::string("started"))
  })
  let ends = events.filter(event => {
    field(event, "stage") == Some(Json::string("bulk")) &&
    field(event, "status") == Some(Json::string("success"))
  })
  assert_true(starts.length() + warnings.val >= 8)
  assert_true(ends.length() + warnings.val >= 8)
  assert_eq(
    events
    .filter(event => {
      field(event, "errorType") == Some(Json::string("retention_limit"))
    })
    .length(),
    1,
  )
  let ids : Map[String, Bool] = Map([])
  for start in starts {
    ids.set(required(start, "runId"), true)
  }
  assert_eq(ids.length(), starts.length())
  let mut unmatched = 0
  for end in ends {
    if !ids.contains(required(end, "runId")) {
      unmatched += 1
    }
  }
  assert_true(unmatched <= warnings.val)
}

